def criar_entradas(apps, schema_editor):
    """Entrada na data local de `cadastrado_em`, registrada pelo autor do evento de cadastro na auditoria.

    Sem evento de cadastro, usa o autor do primeiro evento do participante; sem nenhum evento (cadastro feito fora
    dos serviços), não cria: a entrada será criada ao corrigir o cadastro, que passa a exigir a data.
    """
    Participante = apps.get_model("participantes", "Participante")
    Movimentacao = apps.get_model("participantes", "Movimentacao")
    EventoAuditoria = apps.get_model("core", "EventoAuditoria")
    eventos = EventoAuditoria.objects.filter(tipo="RegistroParticipante").order_by("registrado_em", "pk")
    autor_cadastro, autor_primeiro = {}, {}
    for alvo_id, acao, usuario_id in eventos.values_list("alvo_id", "acao", "usuario_id"):
        if acao == "cadastro":
            autor_cadastro.setdefault(alvo_id, usuario_id)
        autor_primeiro.setdefault(alvo_id, usuario_id)
    novas = []
    for pk, cadastrado_em in Participante.objects.exclude(movimentacoes__tipo="entrada").values_list("pk", "cadastrado_em"):
        usuario_id = autor_cadastro.get(pk, autor_primeiro.get(pk))
        if usuario_id is not None:
            novas.append(Movimentacao(participante_id=pk, tipo="entrada", usuario_id=usuario_id,
                                      data=timezone.localtime(cadastrado_em).date()))
    Movimentacao.objects.bulk_create(novas, batch_size=500)


